package org.apache.commons.lang3.text;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.apache.commons.lang3.AbstractLangTest;
import org.junit.jupiter.api.Test;

/**
 * Tests {@link StrMatcher#commaMatcher()}.
 */
@Deprecated
public class StrMatcherTest_testCommaMatcher extends AbstractLangTest {

    /** Result returned by {@link StrMatcher#isMatch} when no characters match. */
    private static final int NO_MATCH = 0;

    /** Result returned by {@link StrMatcher#isMatch} when a single character matches. */
    private static final int ONE_CHAR_MATCH = 1;

    /**
     * Sample text whose character at each index is known:
     * index 0 is '0', index 1 is the comma, and index 2 is '1'.
     */
    private static final char[] TEXT = "0,1\t2 3\n\r\f�'\"".toCharArray();

    @Test
    void testCommaMatcher() {
        final StrMatcher commaMatcher = StrMatcher.commaMatcher();

        // The factory always returns the same shared instance.
        assertSame(commaMatcher, StrMatcher.commaMatcher());

        // Only the comma at index 1 is matched; the surrounding digits are not.
        assertEquals(NO_MATCH, commaMatcher.isMatch(TEXT, 0));
        assertEquals(ONE_CHAR_MATCH, commaMatcher.isMatch(TEXT, 1));
        assertEquals(NO_MATCH, commaMatcher.isMatch(TEXT, 2));
    }
}
